	public int bonusLootLevels()
	{
		int num = 0;
		float num2 = 0f;
		num2 += (float)character.adventure.itopod.perkLevel[25] * 0.01f;
		if (character.inventory.itemList.gaudyComplete)
		{
			num2 += 0.1f;
		}
		if (character.adventure.itopod.perkLevel[94] >= 144)
		{
			num2 += 0.05f;
		}
		if (Random.value < num2)
		{
			num++;
		}
		if (num < 0)
		{
			num = 0;
		}
		if (num > 100)
		{
			num = 100;
		}
		return num;
	}

	public string makeLoot(int id)
	{
		if (id == 0)
		{
			return "";
		}
		character.allItemList.markItemAsDropped(id);
		Equipment equipment = new Equipment(type[id], bossRequired[id], curAttack[id], capAttack[id], curDefense[id], capDefense[id], specType1[id], curSpec1[id], capSpec1[id], specType2[id], curSpec2[id], capSpec2[id], specType3[id], curSpec3[id], capSpec3[id], path[id], id);
		if (equipment != null)
		{
			if (character.arbitrary.lootFilter && character.inventory.itemList.itemFiltered[equipment.id])
			{
				if (character.arbitrary.hasCubeFilter && equipment.isBoost())
				{
					cubeFilter(equipment);
				}
				return itemName[id];
			}
			if (character.purchases.hasFilter && character.settings.filterOn && ((equipment.type == part.Accessory && character.settings.filterAccessory) || (equipment.type == part.Head && character.settings.filterHead) || (equipment.type == part.Chest && character.settings.filterChest) || (equipment.type == part.Legs && character.settings.filterLegs) || (equipment.type == part.Boots && character.settings.filterBoots) || (equipment.type == part.Weapon && character.settings.filterWeapon) || (equipment.type == part.atkBoost && character.settings.filterBoostAtk) || (equipment.type == part.defBoost && character.settings.filterBoostDef) || (equipment.type == part.specBoost && character.settings.filterBoostSpec) || (equipment.type == part.Misc && character.settings.filterMisc)))
			{
				if (character.arbitrary.hasCubeFilter && equipment.isBoost())
				{
					cubeFilter(equipment);
				}
				return itemName[id];
			}
			if (equipment.level > 0 && equipment.level < 100)
			{
				equipment.level += bonusLootLevels();
			}
			if (character.settings.autoTransform >= 1 && character.settings.autoTransform <= 3 && equipment.isBoost())
			{
