	public void wipeInventory()
	{
		Equipment equipment = new Equipment();
		for (int i = 0; i < character.inventory.inventory.Count; i++)
		{
			character.inventory.inventory[i] = equipment;
		}
		for (int j = 0; j < character.inventory.accs.Count; j++)
		{
			character.inventory.accs[j] = equipment;
		}
		character.inventory.head = equipment;
		character.inventory.chest = equipment;
		character.inventory.legs = equipment;
		character.inventory.boots = equipment;
		character.inventory.weapon = equipment;
		character.inventory.trash = equipment;
		ic.updateInventory();
	}

	public string endRemark()
	{
		int num = Random.Range(0, suffixes.Length);
		return suffixes[num];
	}

	public void testSetCompletion(int a, int b)
	{
		for (int i = a; i <= b; i++)
		{
			makeLevelledLoot(i, 99);
			makeLevelledLoot(i, 99);
		}
	}

	public int addLoot(Equipment loot)
	{
		if (loot.id == 0)
		{
			return -1;
		}
		int num = character.inventoryController.totalInvMergeSlots();
		if (num < 0)
		{
			num = 0;
		}
		for (int i = num; i < character.inventoryController.curSpaces(); i++)
		{
			if (character.inventory.inventory[i].id == 0)
			{
				character.inventory.inventory[i] = null;
				character.inventory.inventory[i] = loot;
				return i;
			}
		}
		return -1;
	}

	public void cubeFilter(Equipment item)
	{
		if (character.arbitrary.hasCubeFilter && item.isBoost())
		{
			float num = 100f;
			if (character.adventure.itopod.perkLevel[26] >= 1)
			{
				num = 50f;
			}
			num /= character.wishesController.totalBoostRatioDivider();
			if (item.type == part.specBoost)
			{
				character.inventory.cubePower += item.spec1Cap * character.allItemList.boostBonus() / (num * 2f);
				character.inventory.cubeToughness += item.spec1Cap * character.allItemList.boostBonus() / (num * 2f);
			}
			else if (item.type == part.atkBoost)
			{
				character.inventory.cubePower += item.capAttack * character.allItemList.boostBonus() / num;
			}
			else if (item.type == part.defBoost)
			{
				character.inventory.cubeToughness += item.capDefense * character.allItemList.boostBonus() / num;
			}
		}
	}

	public Equipment autoTransform(Equipment item, int type)
	{
		if (type < 1 || type > 3)
		{
			return new Equipment();
		}
		if (item.id > 39 || item.id < 1)
		{
			return new Equipment();
		}
		int num = item.id % 13;
		int num2 = item.level;
		num = ((num != 0) ? (num + (type - 1) * 13) : (type * 13));
		Equipment equipment = genLoot(num, dontmark: false);
		equipment.level = num2;
		return equipment;
	}

	public int findItemToDelete(int target)
	{
		for (int i = 0; i < character.inventory.inventory.Count; i++)
		{
			if (character.inventory.inventory[i].id == target && character.inventory.inventory[i].removable)
			{
				return i;
			}
		}
		return -1;
	}

	public int findIndexWithID(int target)
	{
		for (int i = 0; i < character.inventory.inventory.Count; i++)
		{
			if (character.inventory.inventory[i].id == target)
			{
				return i;
			}
		}
		return -1;
	}
